tinymce.PluginManager.add('dotimageclipboard', function(editor, url) {
    // TinyMCE 8's `windowManager.openUrl` replaces the old `windowManager.open` + the
    // `compat3x/tiny_mce_popup.js` bridge (removed entirely from the 8.x distribution — see
    // dialog.jsp/js/dialog.js, which now `postMessage` back here instead of reaching into a
    // global `tinyMCEPopup.editor`).
    function openClipboard() {
        return editor.windowManager.openUrl({
            title: "dotCMS Image Clipboard",
            url: url + '/dialog.jsp',
            width: 550,
            height: 460,
            onMessage: function(dialogApi, details) {
                if (details.mceAction !== 'dotImageClipboardInsert') {
                    return;
                }

                editor.execCommand('mceInsertRawHTML', false, details.html);
                dialogApi.close();
            }
        });
    }

    // Add a button that opens the clipboard dialog
    editor.ui.registry.addButton('dotimageclipboard', {
        icon: 'image',
        tooltip: "Clipboard",
        onAction: openClipboard
    });

    // The original also registered a 'tools' menu item here, but the JSP editor always
    // initializes with `menubar: false` (no Tools menu exists to attach to), so that menu
    // item was already unreachable — dropped rather than carried forward as dead code.
});
